package com.apocollis.chunksteward.server;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Which path generated a chunk's terrain this session, for {@code /chunksteward chunkinfo}: a terrain worker (a finished
 * worker chunk was installed) or the server thread. A bounded map, oldest entries dropped; a chunk loaded from disk or
 * generated by a generator the pipeline does not serve has no entry.
 */
public final class GenSource {
    public static final String WORKER = "terrain worker";
    public static final String SERVER = "server thread";
    private static final int CAPACITY = 40000;
    private static final Map<Long, String> SOURCES = new LinkedHashMap<Long, String>(1024, 0.75f, false) {
        private static final long serialVersionUID = 1L;

        @Override
        protected boolean removeEldestEntry(Map.Entry<Long, String> eldest) {
            return size() > CAPACITY;
        }
    };

    private GenSource() {
    }

    private static long key(int dimension, int x, int z) {
        return ((long) dimension & 0xFFFFL) << 48 ^ ((long) x & 0xFFFFFFL) << 24 ^ ((long) z & 0xFFFFFFL);
    }

    static void record(int dimension, int x, int z, String source) {
        synchronized (SOURCES) {
            SOURCES.put(key(dimension, x, z), source);
        }
    }

    /** The recorded source of the chunk's terrain, or null. */
    public static String of(int dimension, int x, int z) {
        synchronized (SOURCES) {
            return SOURCES.get(key(dimension, x, z));
        }
    }
}
